CREATE TYPE "public"."scene_audio_status" AS ENUM('ready', 'stale', 'failed');
CREATE TABLE "voice_configurations" ("id" uuid PRIMARY KEY NOT NULL, "owner_user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE restrict, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE cascade, "version" integer DEFAULT 1 NOT NULL, "voice_id" text NOT NULL, "speaking_rate" real NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE UNIQUE INDEX "voice_configurations_project_unique" ON "voice_configurations" USING btree ("project_id");
CREATE INDEX "voice_configurations_owner_project_idx" ON "voice_configurations" USING btree ("owner_user_id","project_id");
CREATE TABLE "pronunciation_entries" ("id" uuid PRIMARY KEY NOT NULL, "owner_user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE restrict, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE cascade, "voice_configuration_id" uuid NOT NULL REFERENCES "voice_configurations"("id") ON DELETE cascade, "phrase" text NOT NULL, "replacement" text NOT NULL, "created_at" timestamp with time zone NOT NULL);
CREATE UNIQUE INDEX "pronunciation_entries_configuration_phrase_unique" ON "pronunciation_entries" USING btree ("voice_configuration_id","phrase");
CREATE INDEX "pronunciation_entries_owner_project_config_idx" ON "pronunciation_entries" USING btree ("owner_user_id","project_id","voice_configuration_id");
CREATE TABLE "scene_audio" ("id" uuid PRIMARY KEY NOT NULL, "owner_user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE restrict, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE cascade, "scene_id" uuid NOT NULL REFERENCES "scenes"("id") ON DELETE cascade, "status" "scene_audio_status" DEFAULT 'stale' NOT NULL, "voice_configuration_version" integer NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE INDEX "scene_audio_owner_project_status_idx" ON "scene_audio" USING btree ("owner_user_id","project_id","status");
CREATE INDEX "scene_audio_scene_idx" ON "scene_audio" USING btree ("scene_id");
CREATE TABLE "caption_tracks" ("id" uuid PRIMARY KEY NOT NULL, "owner_user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE restrict, "project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE cascade, "scene_audio_id" uuid NOT NULL REFERENCES "scene_audio"("id") ON DELETE cascade, "status" "scene_audio_status" DEFAULT 'stale' NOT NULL, "created_at" timestamp with time zone NOT NULL, "updated_at" timestamp with time zone NOT NULL);
CREATE INDEX "caption_tracks_owner_project_status_idx" ON "caption_tracks" USING btree ("owner_user_id","project_id","status");
CREATE INDEX "caption_tracks_audio_idx" ON "caption_tracks" USING btree ("scene_audio_id");
